// Deterministic motion helpers. Same t → same value. No frame memory.

export function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function smoothstep(t) {
  const x = clamp(t, 0, 1);
  return x * x * (3 - 2 * x);
}

export function remap(value, a, b) {
  if (a === b) return value >= b ? 1 : 0;
  return clamp((value - a) / (b - a), 0, 1);
}

export function ramp(t, a, b) {
  return smoothstep(remap(t, a, b));
}

/** Fade in over [enter, enter + fade], hold, fade out over [exit, exit + fade]. */
export function band(t, enter, exit, fade = 0.2) {
  const inn = ramp(t, enter, enter + fade);
  const out = 1 - ramp(t, exit, exit + fade);
  return clamp(Math.min(inn, out), 0, 1);
}

export function springStep(x, v, target, dt, omega, zeta) {
  if (dt <= 0) return { x, v };
  const w = omega;
  const z = zeta;
  if (z < 0.999) {
    const wd = w * Math.sqrt(1 - z * z);
    const e = Math.exp(-z * w * dt);
    const dx = x - target;
    const A = dx;
    const B = (v + z * w * dx) / wd;
    const cos = Math.cos(wd * dt);
    const sin = Math.sin(wd * dt);
    const nx = target + e * (A * cos + B * sin);
    const nv =
      e *
      (-z * w * (A * cos + B * sin) + wd * (-A * sin + B * cos));
    return { x: nx, v: nv };
  }
  const e = Math.exp(-w * dt);
  const dx = x - target;
  const A = dx;
  const B = v + w * dx;
  return {
    x: target + e * (A + B * dt),
    v: e * (B - w * (A + B * dt)),
  };
}

/**
 * Closed-form spring toward piecewise-constant targets.
 * keys: [{ t, value }], sorted. State is at rest on the first key.
 */
export function springTrack(time, keys, { omega = 14, zeta = 0.8 } = {}) {
  if (!keys.length) return 0;
  if (time <= keys[0].t) return keys[0].value;
  let x = keys[0].value;
  let v = 0;
  for (let i = 0; i < keys.length; i++) {
    const t0 = keys[i].t;
    const t1 = i + 1 < keys.length ? keys[i + 1].t : Infinity;
    if (time <= t0) break;
    const dt = Math.min(time, t1) - t0;
    const next = springStep(x, v, keys[i].value, dt, omega, zeta);
    x = next.x;
    v = next.v;
    if (time <= t1) break;
  }
  return x;
}

export function curved(a, b, t, bend = 0.18) {
  const u = smoothstep(clamp(t, 0, 1));
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len = Math.hypot(dx, dy) || 1;
  const amount = Math.min(90, len * bend);
  const cx = (a.x + b.x) / 2 + (-dy / len) * amount;
  const cy = (a.y + b.y) / 2 + (dx / len) * amount;
  const m = 1 - u;
  return {
    x: m * m * a.x + 2 * m * u * cx + u * u * b.x,
    y: m * m * a.y + 2 * m * u * cy + u * u * b.y,
  };
}

export function press(t, at, duration = 0.16) {
  const d = t - at;
  if (d < 0 || d > duration) return 0;
  return Math.sin((d / duration) * Math.PI);
}

export function formatInt(value) {
  const sign = value < 0 ? "-" : "";
  const digits = Math.round(Math.abs(value)).toString();
  return sign + digits.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

import {
  band,
  clamp,
  curved,
  formatInt,
  lerp,
  press,
  ramp,
  springTrack,
} from "./engine.js";

const DURATION = 15;

// 120 BPM. One beat = 0.5s. Something lands on almost every beat.
// 1 logo · 2 expand · 3 connect · 4 cursor · 5 click connect
// 6 PostHog · 7 Start run · 8 click start · 9 project · 10 baseline
// 11 plan · 12 pull request · 13 merge · 14 merged · 15 CTA rises
// 16 dashboard · 17 chart · 18 visitors climb · 19 keep rule
// 20 cursor on the point · 21 tooltip · 22 chart becomes the sparkline
// 23 3,184 · 24 site · 25 @codesbyshivam · 26–27 hold · 28 collapse
// 29 logo · 30 rest, matching frame 0
const T = {
  expand: 0.5,
  clickConnect: 2.0,
  github: 2.02,
  posthog: 2.48,
  startLabel: 2.92,
  clickStart: 3.42,
  toRun: 3.55,
  steps: [3.95, 4.5, 5.0, 5.42],
  toPr: 5.55,
  clickMerge: 6.0,
  toLive: 6.7,
  ctaLift: 7.05,
  toDash: 7.6,
  chartStart: 8.0,
  chartEnd: 9.32,
  tooltipIn: 9.62,
  tooltipOut: 10.4,
  toPay: 10.5,
  url: 11.25,
  handle: 11.8,
  collapse: 13.45,
};

const LOOK = {
  logo: { w: 1080, h: 292, r: 44 },
  connect: { w: 980, h: 860, r: 18 },
  run: { w: 940, h: 980, r: 18 },
  pr: { w: 1040, h: 760, r: 18 },
  live: { w: 1160, h: 1000, r: 16 },
  dash: { w: 1220, h: 1040, r: 18 },
  pay: { w: 1040, h: 980, r: 22 },
};

const SIZE_KEYS = [
  { t: -4, ...LOOK.logo },
  { t: T.expand, ...LOOK.connect },
  { t: T.toRun, ...LOOK.run },
  { t: T.toPr, ...LOOK.pr },
  { t: T.toLive, ...LOOK.live },
  { t: T.toDash, ...LOOK.dash },
  { t: T.toPay, ...LOOK.pay },
  { t: T.collapse, ...LOOK.logo },
];

const LEAD = { omega: 13.2, zeta: 0.78 };
const LAG = { omega: 9.4, zeta: 0.84 };

const DAILY = [340, 352, 338, 360, 344, 356, 328, 380, 410, 440, 455, 470, 500, 529];
const BEFORE = DAILY.slice(0, 7).reduce((sum, value) => sum + value, 0);
const AFTER = DAILY.slice(7).reduce((sum, value) => sum + value, 0);
const LIFT = ((AFTER - BEFORE) / BEFORE) * 100;
const BOUNCE_0 = 68.4;
const BOUNCE_1 = 62.1;
const CONV_0 = 3.2;
const CONV_1 = 3.8;

const STEPS = [
  { title: "Project", detail: "northstar/web · main" },
  { title: "Baseline", detail: "2,418 sessions · 68.4% bounce" },
  { title: "Plan", detail: "Move primary CTA above the fold" },
  { title: "Pull request", detail: "Opened #42" },
];

const $ = (id) => document.getElementById(id);

const els = {
  card: $("card"),
  scenes: {
    logo: $("scene-logo"),
    connect: $("scene-connect"),
    run: $("scene-run"),
    pr: $("scene-pr"),
    live: $("scene-live"),
    dash: $("scene-dash"),
    pay: $("scene-pay"),
  },
  github: $("row-github"),
  posthog: $("row-posthog"),
  githubState: $("github-state"),
  posthogState: $("posthog-state"),
  labelConnect: $("label-connect"),
  labelStart: $("label-start"),
  btnConnect: $("btn-connect"),
  btnMerge: $("btn-merge"),
  labelMerge: $("label-merge"),
  runPercent: $("run-percent"),
  runTrack: $("run-track"),
  runSteps: $("run-steps"),
  planBody: $("plan-body"),
  planFile: $("plan-file"),
  prChip: $("pr-chip"),
  prNote: $("pr-note"),
  fold: $("fold"),
  foldNote: $("fold-note"),
  livePill: $("live-pill"),
  visitors: $("visitors"),
  visitorsDetail: $("visitors-detail"),
  bounce: $("bounce"),
  bounceDetail: $("bounce-detail"),
  conversion: $("conversion"),
  conversionDetail: $("conversion-detail"),
  payNumber: $("pay-number"),
  payDetail: $("pay-detail"),
  payRule: $("pay-rule"),
  payUrl: $("pay-url"),
  payHandle: $("pay-handle"),
  dashHole: $("dash-hole"),
  payHole: $("pay-hole"),
  chartLayer: $("chart-layer"),
  chart: $("chart"),
  area: $("chart-area"),
  line: $("chart-line"),
  halo: $("chart-halo"),
  dot: $("chart-dot"),
  rule: $("chart-rule"),
  ruleLabel: $("chart-rule-label"),
  base: $("chart-base"),
  grid: $("chart-grid"),
  tip: $("tip"),
  tipValue: $("tip-value"),
  cursor: $("cursor"),
  press: $("press"),
  readout: $("readout"),
  scrub: $("scrub"),
};

function keys(pick) {
  return SIZE_KEYS.map((key) => ({ t: key.t, value: pick(key) }));
}

function cardAt(t) {
  const left = springTrack(t, keys((key) => 720 - key.w / 2), LEAD);
  const right = springTrack(t, keys((key) => 720 + key.w / 2), LAG);
  const top = springTrack(t, keys((key) => 720 - key.h / 2), LEAD);
  const bottom = springTrack(t, keys((key) => 720 + key.h / 2), LAG);
  const radius = springTrack(
    t,
    keys((key) => key.r),
    { omega: 11, zeta: 0.82 },
  );
  return {
    left,
    top,
    width: right - left,
    height: bottom - top,
    radius,
  };
}

function sceneMix(t) {
  const fade = 0.18;
  const logo = Math.max(
    band(t, -2, T.expand, fade),
    band(t, T.collapse + 0.28, 30, fade),
  );
  return {
    logo,
    connect: band(t, T.expand + 0.22, T.toRun, fade),
    run: band(t, T.toRun + 0.2, T.toPr, fade),
    pr: band(t, T.toPr + 0.18, T.toLive, fade),
    live: band(t, T.toLive + 0.16, T.toDash, fade),
    dash: band(t, T.toDash + 0.16, T.toPay, fade),
    pay: band(t, T.toPay + 0.22, T.collapse, fade),
  };
}

function drawAt(t) {
  return ramp(t, T.chartStart, T.chartEnd);
}

function chartPoints() {
  const width = 640;
  const height = 230;
  const padX = 18;
  const padY = 28;
  const padB = 18;
  const min = 280;
  const max = 600;
  return DAILY.map((value, index) => ({
    x: padX + (index / (DAILY.length - 1)) * (width - padX * 2),
    y: padY + (1 - (value - min) / (max - min)) * (height - padY - padB),
    value,
  }));
}

const POINTS = chartPoints();

function partial(p) {
  const last = (POINTS.length - 1) * clamp(p, 0, 1);
  const index = Math.floor(last);
  const frac = last - index;
  const used = POINTS.slice(0, index + 1).map((point) => ({ ...point }));
  if (index < POINTS.length - 1) {
    const a = POINTS[index];
    const b = POINTS[index + 1];
    used.push({
      x: lerp(a.x, b.x, frac),
      y: lerp(a.y, b.y, frac),
      value: lerp(a.value, b.value, frac),
    });
  }
  return used;
}

function linePath(points) {
  return points
    .map((point, index) => `${index ? "L" : "M"}${point.x.toFixed(2)} ${point.y.toFixed(2)}`)
    .join(" ");
}

function show(el, amount) {
  const visible = amount > 0.015;
  el.style.visibility = visible ? "visible" : "hidden";
  el.style.opacity = amount.toFixed(4);
  el.style.filter = amount > 0.985 ? "none" : `blur(${((1 - amount) * 8).toFixed(2)}px)`;
  const scale = lerp(0.986, 1, amount);
  el.style.transform = `translate(-50%, -50%) scale(${scale.toFixed(4)})`;
}

function textSwap(outEl, inEl, outAmount, inAmount) {
  outEl.style.opacity = outAmount.toFixed(3);
  inEl.style.opacity = inAmount.toFixed(3);
  outEl.style.filter = outAmount > 0.98 ? "none" : `blur(${((1 - outAmount) * 6).toFixed(2)}px)`;
  inEl.style.filter = inAmount > 0.98 ? "none" : `blur(${((1 - inAmount) * 6).toFixed(2)}px)`;
}

function holeBox(card, look, hole) {
  return {
    left: (card.width - look.w) / 2 + hole.offsetLeft,
    top: (card.height - look.h) / 2 + hole.offsetTop,
    width: hole.offsetWidth,
    height: hole.offsetHeight,
  };
}

function mixBox(a, b, p) {
  return {
    left: lerp(a.left, b.left, p),
    top: lerp(a.top, b.top, p),
    width: lerp(a.width, b.width, p),
    height: lerp(a.height, b.height, p),
  };
}

function cursorScript() {
  return [
    { t: 0, pos: "home", opacity: 0 },
    { t: 1.15, pos: "home", opacity: 0 },
    { t: 1.55, pos: "connect", opacity: 1 },
    { t: T.clickStart + 0.12, pos: "connect", opacity: 1 },
    { t: 4.15, pos: "steps", opacity: 1 },
    { t: 5.2, pos: "plan", opacity: 1 },
    { t: 5.85, pos: "merge", opacity: 1 },
    { t: 6.45, pos: "merge", opacity: 1 },
    { t: 7.35, pos: "watch", opacity: 1 },
    { t: 8.35, pos: "aside", opacity: 1 },
    { t: 9.5, pos: "chart", opacity: 1 },
    { t: 10.85, pos: "chart", opacity: 1 },
    { t: 12.05, pos: "home", opacity: 1 },
    { t: 12.55, pos: "home", opacity: 0 },
    { t: 15, pos: "home", opacity: 0 },
  ];
}

function resolve(name, t, card, chart) {
  const place = (look, x, y) => ({
    x: card.left + (card.width - look.w) / 2 + x,
    y: card.top + (card.height - look.h) / 2 + y,
  });
  if (name === "home") return { x: 1270, y: 1260 };
  if (name === "connect") {
    return place(LOOK.connect, LOOK.connect.w / 2, LOOK.connect.h - 48 - 29);
  }
  if (name === "steps") return place(LOOK.run, 78, 430);
  if (name === "plan") return place(LOOK.run, 220, LOOK.run.h - 120);
  if (name === "merge") return place(LOOK.pr, 48 + 140, LOOK.pr.h - 40 - 28);
  if (name === "watch") return place(LOOK.live, 780, 640);
  if (name === "aside") {
    return {
      x: card.left + chart.left + chart.width * 0.42,
      y: card.top + chart.top + chart.height * 0.72,
    };
  }
  const tip = partial(1).at(-1);
  return {
    x: card.left + chart.left + (tip.x / 640) * chart.width + 2,
    y: card.top + chart.top + (tip.y / 230) * chart.height + 2,
  };
}

function cursorAt(t, card, chart) {
  const script = cursorScript();
  let index = 0;
  for (let i = 0; i < script.length - 1; i++) {
    if (t >= script[i].t) index = i;
  }
  const a = script[index];
  const b = script[Math.min(index + 1, script.length - 1)];
  const span = Math.max(0.0001, b.t - a.t);
  const u = clamp((t - a.t) / span, 0, 1);
  const opacity = lerp(a.opacity, b.opacity, ramp(t, a.t, b.t));
  let point;
  if (a.pos === b.pos) point = resolve(a.pos, t, card, chart);
  else {
    point = curved(
      resolve(a.pos, a.t, cardAt(a.t), chart),
      resolve(b.pos, b.t, cardAt(b.t), chart),
      u,
      index % 2 === 0 ? 0.16 : -0.16,
    );
  }
  return { ...point, opacity };
}

function activeScene(mix) {
  return Object.entries(mix).sort((a, b) => b[1] - a[1])[0][0];
}

function apply(t) {
  const card = cardAt(t);
  const mix = sceneMix(t);
  const draw = drawAt(t);
  const kept = BOUNCE_0 - lerp(BOUNCE_0, BOUNCE_1, draw) >= 5;
  const visitors = Math.round(lerp(BEFORE, AFTER, draw));
  const bounce = lerp(BOUNCE_0, BOUNCE_1, draw);
  const conversion = lerp(CONV_0, CONV_1, draw);
  const github = ramp(t, T.github, T.github + 0.22);
  const posthog = ramp(t, T.posthog, T.posthog + 0.22);
  const merged = ramp(t, T.clickMerge + 0.05, T.clickMerge + 0.22);
  const fold = springTrack(t, [
    { t: -4, value: 250 },
    { t: T.ctaLift, value: 18 },
  ], { omega: 8.5, zeta: 0.86 });
  const morph = ramp(t, T.toPay, T.toPay + 0.4);
  const chartOpacity = clamp(mix.dash + mix.pay, 0, 1);

  els.card.style.left = `${card.left}px`;
  els.card.style.top = `${card.top}px`;
  els.card.style.width = `${card.width}px`;
  els.card.style.height = `${card.height}px`;
  els.card.style.borderRadius = `${card.radius}px`;

  for (const [name, el] of Object.entries(els.scenes)) show(el, mix[name]);

  els.github.classList.toggle("on", github > 0.65);
  els.posthog.classList.toggle("on", posthog > 0.65);
  els.githubState.textContent = github > 0.5 ? "Connected" : "Not connected";
  els.posthogState.textContent = posthog > 0.5 ? "Connected" : "Not connected";
  const connectOut = 1 - ramp(t, T.startLabel, T.startLabel + 0.1);
  const startIn = ramp(t, T.startLabel + 0.1, T.startLabel + 0.24);
  textSwap(els.labelConnect, els.labelStart, connectOut, startIn);
  const connectPress = press(t, T.clickConnect);
  els.btnConnect.style.transform = `scale(${(1 - connectPress * 0.035).toFixed(4)})`;

  const done = T.steps.filter((time) => t > time + 0.16).length;
  const current = T.steps.findIndex((time) => t < time + 0.16);
  els.runPercent.textContent = `${Math.round((done / T.steps.length) * 100)}%`;
  els.runTrack.style.transform = `scaleX(${(done / T.steps.length).toFixed(4)})`;
  [...els.runSteps.children].forEach((li, index) => {
    const state = index < done ? "done" : index === current ? "now" : "pending";
    li.className = state;
    const rail = li.querySelector(".rail i");
    if (rail) rail.style.transform = `scaleY(${index < done ? 1 : 0})`;
    const spin = li.querySelector(".spin");
    if (spin) spin.style.transform = `rotate(${((t * 280) % 360).toFixed(2)}deg)`;
  });
  const planIn = ramp(t, T.steps[2], T.steps[2] + 0.2);
  els.planBody.textContent = planIn > 0.5
    ? "Move the primary CTA above the fold."
    : "Reading bounce, scroll, and time on page.";
  els.planFile.textContent = planIn > 0.5 ? "pricing/index.html" : "northstar/web";

  els.prChip.textContent = merged > 0.5 ? "Merged" : "Open";
  els.prChip.classList.toggle("on", merged > 0.5);
  els.prNote.textContent = merged > 0.5
    ? "Merged. The pricing page is live."
    : "One change. The next step moves into view.";
  els.labelMerge.textContent = merged > 0.5 ? "Merged" : "Merge pull request";
  els.btnMerge.classList.toggle("quiet", merged > 0.5);
  const mergePress = press(t, T.clickMerge);
  els.btnMerge.style.transform = `scale(${(1 - mergePress * 0.035).toFixed(4)})`;

  els.fold.style.height = `${fold.toFixed(2)}px`;
  els.foldNote.style.opacity = (1 - ramp(t, T.ctaLift, T.ctaLift + 0.2)).toFixed(3);
  els.livePill.style.opacity = ramp(t, T.ctaLift + 0.28, T.ctaLift + 0.48).toFixed(3);

  els.visitors.textContent = formatInt(visitors);
  els.visitorsDetail.textContent = `↑ ${LIFT.toFixed(1)}% from ${formatInt(BEFORE)}`;
  els.visitorsDetail.style.opacity = ramp(t, T.chartStart + 0.15, T.chartStart + 0.4).toFixed(3);
  els.bounce.textContent = `${bounce.toFixed(1)}%`;
  els.bounceDetail.textContent = kept ? "Kept · −6.3 pts" : "Need −5 pts";
  els.bounceDetail.style.color = kept ? "var(--success)" : "var(--muted)";
  els.conversion.textContent = `${conversion.toFixed(1)}%`;
  els.conversionDetail.textContent = draw > 0.85 ? "↑ 18.7%" : "Baseline";
  els.conversionDetail.style.color = draw > 0.85 ? "var(--success)" : "var(--muted)";

  els.payNumber.textContent = formatInt(AFTER);
  els.payDetail.textContent = `↑ ${LIFT.toFixed(1)}% from ${formatInt(BEFORE)} last week`;
  els.payUrl.style.opacity = ramp(t, T.url, T.url + 0.2).toFixed(3);
  els.payHandle.style.opacity = ramp(t, T.handle, T.handle + 0.2).toFixed(3);

  const dashHole = holeBox(card, LOOK.dash, els.dashHole);
  const payHole = holeBox(card, LOOK.pay, els.payHole);
  const chart = mixBox(dashHole, payHole, morph);
  els.chartLayer.style.opacity = chartOpacity.toFixed(4);
  els.chartLayer.style.visibility = chartOpacity < 0.02 ? "hidden" : "visible";
  els.chartLayer.style.left = `${chart.left}px`;
  els.chartLayer.style.top = `${chart.top}px`;
  els.chartLayer.style.width = `${chart.width}px`;
  els.chartLayer.style.height = `${chart.height}px`;
  els.chartLayer.style.filter = chartOpacity > 0.98 ? "none" : `blur(${((1 - chartOpacity) * 6).toFixed(2)}px)`;

  const drawn = partial(Math.max(draw, morph));
  const tip = drawn.at(-1);
  const d = linePath(drawn);
  const baseY = 230 - 18;
  els.line.setAttribute("d", d);
  els.area.setAttribute(
    "d",
    `${d} L${tip.x.toFixed(2)} ${baseY} L${drawn[0].x.toFixed(2)} ${baseY} Z`,
  );
  els.dot.setAttribute("cx", tip.x.toFixed(2));
  els.dot.setAttribute("cy", tip.y.toFixed(2));
  els.halo.setAttribute("cx", tip.x.toFixed(2));
  els.halo.setAttribute("cy", tip.y.toFixed(2));
  els.dot.style.opacity = draw > 0.02 || morph > 0.2 ? "1" : "0";
  els.halo.style.opacity = morph > 0.45 ? "0" : els.dot.style.opacity;
  const ruleX = (POINTS[6].x + POINTS[7].x) / 2;
  const ruleY = POINTS[6].y;
  els.base.setAttribute("y1", POINTS[0].y.toFixed(2));
  els.base.setAttribute("y2", POINTS[0].y.toFixed(2));
  els.rule.setAttribute("x1", ruleX.toFixed(2));
  els.rule.setAttribute("x2", ruleX.toFixed(2));
  els.rule.setAttribute("y1", "22");
  els.rule.setAttribute("y2", String(baseY));
  els.ruleLabel.setAttribute("x", (ruleX + 8).toFixed(2));
  els.ruleLabel.setAttribute("y", "18");
  const chrome = (1 - morph) * (draw > 0.48 ? 1 : ramp(draw, 0.42, 0.5));
  els.rule.style.opacity = chrome.toFixed(3);
  els.ruleLabel.style.opacity = chrome.toFixed(3);
  els.base.style.opacity = (1 - morph).toFixed(3);
  els.grid.style.opacity = (1 - morph).toFixed(3);

  const tipOn = band(t, T.tooltipIn, T.tooltipOut, 0.12);
  const tipX = (tip.x / 640) * chart.width;
  const tipY = (tip.y / 230) * chart.height;
  els.tip.style.opacity = tipOn.toFixed(3);
  els.tip.style.left = `${(tipX - 168).toFixed(1)}px`;
  els.tip.style.top = `${(tipY - 74).toFixed(1)}px`;
  els.tipValue.textContent = formatInt(Math.round(tip.value));

  const cursor = cursorAt(t, card, chart);
  const click =
    press(t, T.clickConnect) + press(t, T.clickStart) + press(t, T.clickMerge);
  const cursorScale = 1 - Math.min(click, 1) * 0.12;
  els.cursor.style.opacity = cursor.opacity.toFixed(3);
  els.cursor.style.visibility = cursor.opacity < 0.02 ? "hidden" : "visible";
  els.cursor.style.transform = `translate(${cursor.x.toFixed(2)}px, ${cursor.y.toFixed(2)}px) scale(${cursorScale.toFixed(3)})`;
  els.press.style.opacity = (Math.min(click, 1) * 0.85).toFixed(3);
  els.press.style.transform = `translate(${cursor.x.toFixed(2)}px, ${cursor.y.toFixed(2)}px) scale(${lerp(0.4, 1.6, Math.min(click, 1)).toFixed(3)})`;

  const scene = activeScene(mix);
  const beat = Math.min(30, Math.floor(t / 0.5) + 1);
  if (!document.body.classList.contains("capture")) {
    els.readout.textContent = `${t.toFixed(2)}s   f${Math.round(t * 60)}   beat ${beat}   ${scene}   cursor ${cursor.x.toFixed(0)}, ${cursor.y.toFixed(0)}   cam 1.000   card ${card.width.toFixed(0)}×${card.height.toFixed(0)}`;
    if (document.activeElement !== els.scrub) els.scrub.value = String(t);
  }

  return { t, card, mix, cursor, scene, draw, visitors, kept };
}

function buildSteps() {
  STEPS.forEach((step, index) => {
    const li = document.createElement("li");
    li.className = "pending";
    li.innerHTML = `
      <div>
        <div class="bubble"><span class="num">${index + 1}</span><span class="spin" style="display:none"></span></div>
        <div class="rail"><i></i></div>
      </div>
      <div>
        <p class="title"></p>
        <p class="detail"></p>
      </div>`;
    li.querySelector(".title").textContent = step.title;
    li.querySelector(".detail").textContent = step.detail;
    if (index === STEPS.length - 1) li.querySelector(".rail").remove();
    els.runSteps.appendChild(li);
  });
}

function buildGrid() {
  for (let i = 0; i < 4; i++) {
    const y = 28 + (i / 3) * (230 - 46);
    const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
    line.setAttribute("x1", "16");
    line.setAttribute("x2", "624");
    line.setAttribute("y1", y.toFixed(2));
    line.setAttribute("y2", y.toFixed(2));
    line.setAttribute("stroke", "oklch(0.93 0.01 150)");
    els.grid.appendChild(line);
  }
}

function layoutScenes() {
  for (const [name, look] of Object.entries(LOOK)) {
    const scene = els.scenes[name];
    scene.style.width = `${look.w}px`;
    scene.style.height = `${look.h}px`;
  }
  const pad = {
    connect: "44px 52px 48px",
    run: "40px 48px 44px",
    pr: "40px 48px 40px",
    live: "32px 32px 32px",
    dash: "40px 44px 28px",
    pay: "56px 56px 48px",
  };
  for (const [name, value] of Object.entries(pad)) {
    els.scenes[name].style.padding = value;
  }
  els.btnConnect.style.marginTop = "auto";
  els.btnConnect.style.height = "58px";
  els.btnMerge.style.marginTop = "28px";
  els.btnMerge.style.width = "280px";
  els.btnMerge.style.height = "56px";
}

let playing = false;
let last = 0;
let time = 0;

function tick(now) {
  if (!playing) return;
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  time = (time + dt) % DURATION;
  apply(time);
  requestAnimationFrame(tick);
}

function boot() {
  if (BEFORE !== 2418 || AFTER !== 3184) {
    throw new Error(`Visitor totals drifted: ${BEFORE} / ${AFTER}`);
  }
  buildSteps();
  buildGrid();
  layoutScenes();
  const params = new URLSearchParams(location.search);
  if (params.has("capture")) document.body.classList.add("capture");
  const initial = Number(params.get("t") ?? 0);
  time = Number.isFinite(initial) ? clamp(initial, 0, DURATION) : 0;
  apply(time);

  $("play").addEventListener("click", () => {
    playing = !playing;
    $("play").textContent = playing ? "Pause" : "Play";
    last = performance.now();
    if (playing) requestAnimationFrame(tick);
  });
  els.scrub.addEventListener("input", () => {
    playing = false;
    $("play").textContent = "Play";
    time = Number(els.scrub.value);
    apply(time);
  });
  window.addEventListener("keydown", (event) => {
    if (event.key === " ") {
      event.preventDefault();
      $("play").click();
    } else if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
      const step = event.shiftKey ? 0.5 : 1 / 60;
      time = clamp(time + (event.key === "ArrowRight" ? step : -step), 0, DURATION);
      playing = false;
      apply(time);
    }
  });
}

window.seek = (t) => apply(clamp(t, 0, DURATION));
window.__sample = (t) => apply(clamp(t, 0, DURATION));
window.__DURATION = DURATION;

boot();

