import { createHash } from "node:crypto";
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright-core";

const root = path.dirname(fileURLToPath(import.meta.url));
const outDir = path.join(root, "out");
const args = new Set(process.argv.slice(2));
const beatsOnly = args.has("--beats");
const noBlur = args.has("--no-blur");
const atFlag = process.argv.indexOf("--at");
const atTime = atFlag >= 0 ? Number(process.argv[atFlag + 1]) : null;

const types = {
  ".html": "text/html",
  ".js": "text/javascript",
  ".css": "text/css",
  ".svg": "image/svg+xml",
  ".woff2": "font/woff2",
  ".woff": "font/woff",
  ".png": "image/png",
};

function serve() {
  return new Promise((resolve) => {
    const server = createServer(async (req, res) => {
      const url = new URL(req.url ?? "/", "http://127.0.0.1");
      const file = path.join(root, decodeURIComponent(url.pathname));
      if (!file.startsWith(root)) {
        res.writeHead(403);
        res.end();
        return;
      }
      try {
        const body = await readFile(file);
        res.writeHead(200, { "content-type": types[path.extname(file)] ?? "application/octet-stream" });
        res.end(body);
      } catch {
        res.writeHead(404);
        res.end();
      }
    });
    server.listen(0, "127.0.0.1", () => resolve(server));
  });
}

function ffmpeg(ffmpegArgs) {
  return new Promise((resolve, reject) => {
    const child = spawn("ffmpeg", ffmpegArgs, { stdio: "inherit" });
    child.on("exit", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`ffmpeg exited ${code}`));
    });
  });
}

async function shot(page, file) {
  await page.locator("#viewport").screenshot({ path: file, type: "png" });
}

async function main() {
  await mkdir(outDir, { recursive: true });
  const server = await serve();
  const { port } = server.address();
  const browser = await chromium.launch({
    channel: "chrome",
    headless: true,
    args: ["--font-render-hinting=medium"],
  });
  const page = await browser.newPage({
    viewport: { width: 1440, height: 1440 },
    deviceScaleFactor: 1,
  });
  await page.goto(`http://127.0.0.1:${port}/index.html?capture=1`, {
    waitUntil: "networkidle",
  });
  await page.evaluate(async () => {
    await document.fonts.ready;
    if (!document.fonts.check("700 80px Manrope")) throw new Error("Manrope did not load");
    if (!document.fonts.check("16px 'DM Sans'")) throw new Error("DM Sans did not load");
  });

  const loop = await page.evaluate(() => {
    const a = window.__sample(0);
    const b = window.__sample(15);
    const cardClose = (left, right) => Math.abs(left - right) < 0.25;
    return {
      ok:
        cardClose(a.card.width, b.card.width) &&
        cardClose(a.card.height, b.card.height) &&
        cardClose(a.card.left, b.card.left) &&
        cardClose(a.card.top, b.card.top) &&
        cardClose(a.cursor.x, b.cursor.x) &&
        cardClose(a.cursor.opacity, b.cursor.opacity) &&
        Math.abs(a.mix.logo - b.mix.logo) < 0.01 &&
        a.mix.connect < 0.01 &&
        b.mix.connect < 0.01,
      a: { card: a.card, cursor: a.cursor, mix: a.mix },
      b: { card: b.card, cursor: b.cursor, mix: b.mix },
    };
  });
  if (!loop.ok) {
    console.error(JSON.stringify(loop, null, 2));
    throw new Error("Frame 0 and frame 15 do not match");
  }
  console.log("loop closed");

  if (atTime != null) {
    await page.evaluate((t) => window.seek(t), atTime);
    await shot(page, path.join(outDir, `at-${atTime.toFixed(2)}.png`));
  } else if (beatsOnly || true) {
    const beatDir = path.join(outDir, "beats");
    await mkdir(beatDir, { recursive: true });
    for (let i = 0; i < 30; i++) {
      const t = i * 0.5;
      await page.evaluate((time) => window.seek(time), t);
      const scene = await page.evaluate(() => document.getElementById("readout")?.textContent ?? "");
      await shot(page, path.join(beatDir, `beat-${String(i).padStart(2, "0")}.png`));
      console.log(`beat ${i + 1} t=${t.toFixed(1)} ${scene}`);
    }
    await ffmpeg([
      "-y",
      "-framerate",
      "1",
      "-start_number",
      "0",
      "-i",
      path.join(beatDir, "beat-%02d.png"),
      "-vf",
      "tile=6x5:padding=10:margin=10:color=0xE6EEE6",
      "-frames:v",
      "1",
      path.join(outDir, "sheet.png"),
    ]);
    console.log("wrote", path.join(outDir, "sheet.png"));
  }

  if (!beatsOnly && atTime == null) {
    const sampleDir = path.join(outDir, "samples");
    await rm(sampleDir, { recursive: true, force: true });
    await mkdir(sampleDir, { recursive: true });
    const fps = noBlur ? 60 : 240;
    const frames = 15 * fps;
    for (let i = 0; i < frames; i++) {
      const t = (i / fps) % 15;
      await page.evaluate((time) => window.seek(time), t);
      await shot(page, path.join(sampleDir, `f_${String(i + 1).padStart(5, "0")}.png`));
      if (i % 120 === 0) console.log(`frame ${i + 1}/${frames}`);
    }
    const filters = noBlur ? [] : ["-vf", "tmix=frames=4:weights='1 1 1 1',fps=60"];
    await ffmpeg([
      "-y",
      "-framerate",
      String(fps),
      "-i",
      path.join(sampleDir, "f_%05d.png"),
      ...filters,
      "-c:v",
      "libx264",
      "-pix_fmt",
      "yuv420p",
      "-crf",
      "16",
      "-preset",
      "slow",
      "-movflags",
      "+faststart",
      path.join(outDir, "friction-fixer.mp4"),
    ]);
    await rm(sampleDir, { recursive: true, force: true });
    const hash = createHash("sha256");
    hash.update(await readFile(path.join(outDir, "friction-fixer.mp4")));
    console.log("video", path.join(outDir, "friction-fixer.mp4"));
  }

  await browser.close();
  server.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

